import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow } from '../_helpers/milestone';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

const routes = [
  '/home',
  '/journey',
  '/journey/history',
  '/profile',
  '/zmanim',
  '/prayers',
  '/lessons',
  '/tehilim',
  '/tehilim/72',
  '/prayer/mincha_ashkenaz',
  '/blessings',
];

test.describe('Уникальные id — вошедший пользователь', () => {
  test('A11Y-02 Все id в DOM уникальны — маршруты user1 #6a905ceb @prod-safe @mobile', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. По очереди открыть маршруты.
    for (const url of routes) {
      await test.step(url, async () => {
        await page.goto(url);
        await expect(page).toHaveTitle(/אור הגאולה/);
        await expect(page.locator('[id]').first()).toBeAttached();

        // 2. Найти повторы id.
        await expect
          .poll(() =>
            page.evaluate(() => {
              const ids = [...document.querySelectorAll('[id]')].map((e) => e.id);
              return ids.filter((id, i) => ids.indexOf(id) !== i);
            }),
          )
          .toEqual([]);
      });
    }
  });
});
